    fn select_current(opts: &[SessionConfigOption], id: &str) -> Option<String> {
        opts.iter().find_map(|opt| {
            if &*opt.id.0 != id {
                return None;
            }
            match &opt.kind {
                SessionConfigKind::Select(select) => Some(select.current_value.0.to_string()),
                _ => None,
            }
        })
    }

